              ls_fsm_nsC = data_gnt_iC ? IDLE : WAIT_GNT;
              addr_updateC = data_gnt_iC&~ (data_err_iC|pmp_err_qVotedC) ;
              handle_misaligned_dC = ~data_gnt_iC;
            end
          else
            begin
              if (data_gnt_iC)
                begin
                  ls_fsm_nsC = WAIT_RVALID_MIS_GNTS_DONE;
                  handle_misaligned_dC = 1'b0;
                end

            end
        end
      WAIT_GNT : 
        begin
          addr_incr_req_oC = handle_misaligned_qVotedC;
          data_req_oC = 1'b1;
          if (data_gnt_iC||pmp_err_qVotedC)
            begin
              ctrl_updateC = 1'b1;
              addr_updateC = ~lsu_err_qVotedC;
              ls_fsm_nsC = IDLE;
              handle_misaligned_dC = 1'b0;
            end

        end
      WAIT_RVALID_MIS_GNTS_DONE : 
        begin
          addr_incr_req_oC = 1'b1;
          if (data_rvalid_iC)
            begin
              pmp_err_dC = data_pmp_err_iC;
              lsu_err_dC = data_err_iC;
              addr_updateC = ~data_err_iC;
              rdata_updateC = ~data_we_qVotedC;
              ls_fsm_nsC = IDLE;
            end

        end
      default : 
        begin
          ls_fsm_nsC = IDLE;
        end
    endcase
  end

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        ls_fsm_csA <= IDLE;
        handle_misaligned_qA <= '0;
        pmp_err_qA <= '0;
        lsu_err_qA <= '0;
      end
    else
      begin
        ls_fsm_csA <= ls_fsm_nsA;
        handle_misaligned_qA <= handle_misaligned_dA;
        pmp_err_qA <= pmp_err_dA;
        lsu_err_qA <= lsu_err_dA;
      end
  end

